/**
 * Widgetron - Embeddable AI website assistant
 * ES module build - use via: import { init, createProvider } from "widgetron";
 * Do not edit this file directly - edit the source files and rebuild
 * with: node build.js
 */

// ===== providers/provider.js =====
function createProvider({ format, baseUrl, apiKey, model, headers = {} }) {
  if (format === "openai") {
    return {
      async chat({ messages, systemPrompt, signal }) {
        const res = await fetch(baseUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}),
            ...headers,
          },
          body: JSON.stringify({
            model,
            messages: [{ role: "system", content: systemPrompt }, ...messages],
          }),
          signal,
        });

        if (!res.ok) {
          throw new Error(`Request failed: ${res.status}`);
        }

        const data = await res.json();
        return data.choices[0].message.content;
      },
    };
  }

  if (format === "anthropic") {
    return {
      async chat({ messages, systemPrompt, signal }) {
        const res = await fetch(baseUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-api-key": apiKey,
            "anthropic-version": "2023-06-01",
            ...headers,
          },
          body: JSON.stringify({
            model,
            max_tokens: 1024,
            system: systemPrompt,
            messages,
          }),
          signal,
        });

        if (!res.ok) {
          throw new Error(`Request failed: ${res.status}`);
        }

        const data = await res.json();
        return data.content[0].text;
      },
    };
  }

  throw new Error(`Unknown provider format: ${format}`);
}

// ===== public/widget/pageReader.js =====
function readDynamicPage(url, timeoutMs = 4000) {
  const iframeRead = new Promise((resolve, reject) => {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";

    iframe.src = url + (url.includes("?") ? "&" : "?") + "widgetronRead=1";

    iframe.onload = () => {
      try {
        const doc = iframe.contentDocument;
        const text = doc.body.innerText;
        document.body.removeChild(iframe);

        if (
          !text.trim() ||
          /^Cannot (GET|POST|PUT|DELETE)/i.test(text.trim())
        ) {
          reject(new Error(`No real content at ${url} (likely a 404)`));
          return;
        }

        resolve(text);
      } catch (err) {
        document.body.removeChild(iframe);
        reject(new Error(`Could not read ${url} — likely cross-origin`));
      }
    };

    iframe.onerror = () => {
      document.body.removeChild(iframe);
      reject(new Error(`Failed to load ${url}`));
    };

    document.body.appendChild(iframe);
  });

  const timeout = new Promise((_, reject) =>
    setTimeout(() => reject(new Error(`Timed out reading ${url}`)), timeoutMs),
  );

  return Promise.race([iframeRead, timeout]);
}

function readMultiplePages(urls, { timeoutMs = 4000 } = {}) {
  const pagePromises = urls.map((url) => {
    return readDynamicPage(url, timeoutMs)
      .then((content) => {
        return { url, status: "success", content };
      })
      .catch((err) => {
        return { url, status: "failed", error: err.message };
      });
  });
  return Promise.allSettled(pagePromises).then((results) => {
    return results.map((result) => result.value);
  });
}

async function fetchConfiguredAPIs(apiConfigs = [], { timeoutMs = 4000 } = {}) {
  const fetchPromises = apiConfigs.map((config) => {
    const controller = new AbortController();

    const timeoutId = setTimeout(() => {
      controller.abort();
    }, timeoutMs);

    return fetch(config.url, {
      headers: config.headers,
      signal: controller.signal,
    })
      .then((response) => {
        clearTimeout(timeoutId);
        if (!response.ok) {
          throw new Error(`HTTP error! Status: ${response.status}`);
        }
        return response.json().then((data) => ({
          name: config.name,
          status: "success",
          data,
        }));
      })
      .catch((err) => {
        clearTimeout(timeoutId);
        const isTimeout = err.name === "AbortError";

        return {
          name: config.name,
          status: "failed",
          error: isTimeout ? "Request timed out" : err.message,
        };
      });
  });
  return Promise.allSettled(fetchPromises).then((results) => {
    return results.map((result) => result.value);
  });
}

async function gatherFullContext({
  pageUrls = [],
  apiConfigs = [],
  timeoutMs = 4000,
} = {}) {
  return Promise.all([
    readMultiplePages(pageUrls, { timeoutMs }),
    fetchConfiguredAPIs(apiConfigs, { timeoutMs }),
  ]).then(([pageResult, apiResult]) => {
    return {
      pages: pageResult,
      apis: apiResult,
    };
  });
}

// ===== public/widget/chatEngine.js =====
function formatContextForPrompt(context) {
  const successfulPages = context.pages.filter((p) => p.status === "success");
  const successfulApis = context.apis.filter((a) => a.status === "success");

  const pageSections = successfulPages.map(
    (p) => `--- Content from ${p.url} ---\n${p.content}`,
  );

  const apiSections = successfulApis.map(
    (a) => `--- Data from "${a.name}" ---\n${JSON.stringify(a.data, null, 2)}`,
  );

  const combinedText = [...pageSections, ...apiSections].join("\n\n");

  const failedSources = [
    ...context.pages.filter((p) => p.status !== "success").map((p) => p.url),
    ...context.apis.filter((a) => a.status !== "success").map((a) => a.name),
  ];

  return { text: combinedText, failedSources };
}

function parseModelResponse(rawText) {
  try {
    const parsed = JSON.parse(rawText);

    if (
      typeof parsed.answer === "string" &&
      typeof parsed.answerFound === "boolean"
    ) {
      return {
        answer: parsed.answer,
        answerFound: parsed.answerFound,
        wellFormed: true,
      };
    }

    return { answer: rawText, answerFound: null, wellFormed: false };
  } catch {
    return { answer: rawText, answerFound: null, wellFormed: false };
  }
}

function buildSystemPrompt(contextText) {
  const systemPrompt = `
  You are a website assistant embedded in a chat widget. Your job is to help users based strictly on the provided context.

CRITICAL RULES:
1. You must answer the user's question using ONLY the provided Context Text below. Do not guess, make up information, or use any outside knowledge.
2. Your response must be strictly valid JSON in the exact format specified below. Do not include any introductory text, markdown formatting (like \`\`\`json), or concluding text. Output ONLY the raw JSON object.

You must NEVER claim to have performed an action — such as adding an item to a cart, placing an order, or completing a purchase. You are not able to perform actions; you can only answer informational questions using the context provided.

JSON SHAPE:
{
  "answer": "Your answer string here, or a polite message stating the information was not found.",
  "answerFound": true or false
}

If the answer cannot be found completely within the provided Context Text, you must set "answerFound" to false.

CONTEXT TEXT:
${contextText}
 `.trim();
  return systemPrompt;
}

async function askAssistant({
  userMessage,
  pageUrls,
  apiConfigs,
  chatFn,
  timeoutMs = 4000,
  signal,
  history = [],
}) {
  const rawContext = await gatherFullContext({
    pageUrls,
    apiConfigs,
    timeoutMs,
  });
  const { text, failedSources } = formatContextForPrompt(rawContext);
  const systemPrompt = buildSystemPrompt(text);

  const messages = [
    ...history.map((m) => ({ role: m.role, content: m.text })),
    { role: "user", content: userMessage },
  ];

  const rawReply = await chatFn({ systemPrompt, messages, signal });
  const parsedResult = parseModelResponse(rawReply);

  return { ...parsedResult, failedSources };
}

// ===== public/widget/actionEngine.js =====
const ALLOWED_ACTIONS = ["add_to_cart", "remove_from_cart", "none"];

function parseActionResponse(rawText) {
  try {
    const parsed = JSON.parse(rawText);

    if (
      typeof parsed.action !== "string" ||
      !ALLOWED_ACTIONS.includes(parsed.action)
    ) {
      return { action: "none", item: null, quantity: null, wellFormed: false };
    }

    return {
      action: parsed.action,
      item: typeof parsed.item === "string" ? parsed.item : null,
      quantity: typeof parsed.quantity === "number" ? parsed.quantity : null,
      wellFormed: true,
    };
  } catch {
    return { action: "none", item: null, quantity: null, wellFormed: false };
  }
}

async function executeAction(action, callbacks) {
  const handlers = {
    add_to_cart: () =>
      callbacks.onAddToCart?.(action.item, action.quantity ?? 1),
    remove_from_cart: () =>
      callbacks.onRemoveFromCart?.(action.item, action.quantity),
    none: () => null,
  };

  const handler = handlers[action.action];
  if (!handler) {
    throw new Error(`No handler for action: ${action.action}`);
  }

  return await handler();
}

function buildActionSystemPrompt() {
  const systemPrompt = `
You are an e-commerce intent classification engine. Your sole job is to analyze the user's message and convert their intent into a single, structured JSON object.

CRITICAL RULES:
1. You must classify ONLY the most recent user message into exactly ONE of the three JSON shapes listed below. Earlier messages in the conversation are provided only for context — for example, to resolve "it" or "that" if the user refers back to something mentioned before. Do not re-classify earlier messages.
2. If the user wants to add an item but does not specify a quantity, you MUST default the quantity to 1.
3. If the user's message is not a clear request to add or remove items from a cart, you MUST return the "none" action. Do not try to answer questions or guess intent.
4. Output ONLY the raw JSON object. Do not include introductory text, markdown block formatting (like \`\`\`json), or trailing text.

ACCEPTED JSON SHAPES:

For adding items:
{ 
  "action": "add_to_cart", 
  "item": "Name of the item as a string", 
  "quantity": Integer number 
}

For removing items:
{ 
  "action": "remove_from_cart", 
  "item": "Name of the item as a string", 
  "quantity": null 
}

For unrelated inquiries, questions, or greetings:
{ 
  "action": "none" 
}
  `.trim();
  return systemPrompt;
}

async function askForAction({ userMessage, chatFn, signal, history = [] }) {
  const systemPrompt = buildActionSystemPrompt();
  const messages = [
    ...history.map((m) => ({ role: m.role, content: m.text })),
    { role: "user", content: userMessage },
  ];
  const rawReply = await chatFn({ systemPrompt, messages, signal });
  return parseActionResponse(rawReply);
}

// ===== public/widget/confirmUI.js =====
function formatConfirmationMessage(action) {
  if (action.action === "add_to_cart") {
    const qty = action.quantity ?? 1;
    return `Add ${qty} × ${action.item} to your cart?`;
  }

  if (action.action === "remove_from_cart") {
    return action.quantity
      ? `Remove ${action.quantity} × ${action.item} from your cart?`
      : `Remove ${action.item} from your cart?`;
  }

  return null;
}

function showConfirmDialog(action, callbacks, onResult) {
  const message = formatConfirmationMessage(action);
  if (!message) return;

  const backdrop = document.createElement("div");
  backdrop.className = "widgetron-modal-backdrop";

  const modal = document.createElement("div");
  modal.className = "widgetron-modal";
  modal.innerHTML = `
    <p class="widgetron-modal-message"></p>
    <div class="widgetron-modal-actions">
      <button class="widgetron-modal-cancel">Cancel</button>
      <button class="widgetron-modal-confirm">Confirm</button>
    </div>
  `;
  modal.querySelector(".widgetron-modal-message").textContent = message;

  const close = () => backdrop.remove();

  modal
    .querySelector(".widgetron-modal-confirm")
    .addEventListener("click", async () => {
      const confirmBtn = modal.querySelector(".widgetron-modal-confirm");
      confirmBtn.disabled = true;
      confirmBtn.textContent = "Working...";

      try {
        await executeAction(action, callbacks);
        close();
        onResult?.(action, true, null);
      } catch (err) {
        close();
        onResult?.(action, false, err.message);
      }
    });

  modal
    .querySelector(".widgetron-modal-cancel")
    .addEventListener("click", close);

  backdrop.addEventListener("click", (e) => {
    if (e.target === backdrop) close();
  });

  backdrop.appendChild(modal);
  document.body.appendChild(backdrop);
}

// ===== public/widget/widget.js =====
const ICONS = {
  chat: `<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>`,
  send: `<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>`,
  stop: `<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><rect x="6" y="6" width="12" height="12" rx="2"/></svg>`,
  mic: `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="8" y1="23" x2="16" y2="23"/></svg>`,
};

const SpeechRecognitionAPI =
  window.SpeechRecognition || window.webkitSpeechRecognition;

function isSpeechSupported() {
  return typeof SpeechRecognitionAPI !== "undefined";
}

const HISTORY_KEY = "widgetron-chat-history";

const ACTION_CLAIM_PATTERN =
  /\b(added|removed|placed your order|order (id|#|number)|added to (your|the) cart)\b/i;

function containsActionClaim(text) {
  return ACTION_CLAIM_PATTERN.test(text);
}

function loadHistory() {
  try {
    const raw = sessionStorage.getItem(HISTORY_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveHistory(history) {
  try {
    sessionStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  } catch {
    // sessionStorage can fail in private browsing on some browsers — chat
    // still works for the current page, it just won't persist across nav.
  }
}

function createWidgetDOM(config) {
  const bubble = document.createElement("button");
  bubble.className = "widgetron-bubble";
  bubble.innerHTML = ICONS.chat;

  const panel = document.createElement("div");
  panel.className = "widgetron-panel";
  panel.innerHTML = `
    <div class="widgetron-messages"></div>
    <div class="widgetron-input-row">
      ${
        isSpeechSupported() && config.voice !== false
          ? `<button class="widgetron-mic" type="button" title="Speak">${ICONS.mic}</button>`
          : ""
      }
      <input type="text" placeholder="Ask something..." />
      <button class="widgetron-send" type="button">${ICONS.send}</button>
    </div>
  `;

  // theme: "light" | "dark" forces that palette via the CSS variable
  // overrides. Anything else (unset, "auto") leaves it to the
  // prefers-color-scheme media query in widget.css, which follows the
  // visitor's OS/browser setting automatically.
  // Applied to <html>, not the widget elements themselves, so the confirm
  // modal (mounted separately, straight to document.body) inherits the
  // same variables too.
  if (config.theme === "light" || config.theme === "dark") {
    document.documentElement.dataset.widgetronTheme = config.theme;
  }

  bubble.addEventListener("click", () => {
    panel.classList.toggle("open");
  });

  document.body.appendChild(bubble);
  document.body.appendChild(panel);

  return {
    messagesEl: panel.querySelector(".widgetron-messages"),
    inputEl: panel.querySelector("input"),
    sendBtn: panel.querySelector(".widgetron-send"),
    micBtn: panel.querySelector(".widgetron-mic"), // null if unsupported or disabled
  };
}

function appendMessage(messagesEl, role, text, history) {
  const el = document.createElement("div");
  el.className = `widgetron-message ${role}`;
  el.textContent = text;
  messagesEl.appendChild(el);
  messagesEl.scrollTop = messagesEl.scrollHeight;

  if (history) {
    history.push({ role, text });
    saveHistory(history);
  }

  return el;
}

function showTypingIndicator(messagesEl) {
  const el = document.createElement("div");
  el.className = "widgetron-message assistant widgetron-typing";
  el.innerHTML = `<span></span><span></span><span></span>`;
  messagesEl.appendChild(el);
  messagesEl.scrollTop = messagesEl.scrollHeight;
  return el;
}

function resolveModesForPage(config) {
  const currentPath = window.location.pathname;

  if (config && Array.isArray(config.pageRules)) {
    for (const rule of config.pageRules) {
      let regexPattern = rule.match.replace(/[.+^${}()|[\]\\]/g, "\\$&");
      regexPattern = regexPattern.replace(/\*/g, ".*");
      const pathRegex = new RegExp(`^${regexPattern}$`);
      if (pathRegex.test(currentPath)) {
        return rule.modes;
      }
    }
  }

  return config.modes || ["read"];
}

function formatActionResultMessage(action, success) {
  const qty = action.quantity ?? 1;

  if (!success) {
    return `Sorry, I couldn't complete that — please try again.`;
  }

  if (action.action === "add_to_cart") {
    return `Added ${qty} × ${action.item} to your cart.`;
  }

  if (action.action === "remove_from_cart") {
    return `Removed ${action.item} from your cart.`;
  }

  return "Done.";
}

async function handleSendMessage(text, elements, config, state) {
  // Snapshot BEFORE appending the current message — otherwise the current
  // message ends up duplicated (once from history, once as userMessage).
  const recentHistory = state.history.slice(-6);

  appendMessage(elements.messagesEl, "user", text, state.history);

  const activeModes = resolveModesForPage(config);
  const typingEl = showTypingIndicator(elements.messagesEl);

  const controller = new AbortController();
  state.activeController = controller;
  setSendButtonState(elements.sendBtn, "cancel");

  try {
    let actionResult = null;

    if (activeModes.includes("action")) {
      actionResult = await askForAction({
        chatFn: config.chatFn,
        userMessage: text,
        signal: controller.signal,
        history: recentHistory,
      });
    }

    if (actionResult && actionResult.action !== "none") {
      typingEl.remove();
      showConfirmDialog(
        actionResult,
        {
          onAddToCart: config.onAddToCart,
          onRemoveFromCart: config.onRemoveFromCart,
        },
        (finishedAction, success) => {
          const resultText = formatActionResultMessage(finishedAction, success);
          appendMessage(
            elements.messagesEl,
            "assistant",
            resultText,
            state.history,
          );
        },
      );
      return;
    }

    const assistantResult = await askAssistant({
      chatFn: config.chatFn,
      userMessage: text,
      pageUrls: config.pageUrls,
      apiConfigs: config.apiConfigs,
      signal: controller.signal,
      history: recentHistory,
    });

    let finalAnswer = assistantResult.answer;

    // Backstop against the model claiming an action happened on a page
    // where action mode isn't even active — never trust the model's own
    // claim about performing an action, override it in code regardless of
    // what it says.
    if (!activeModes.includes("action") && containsActionClaim(finalAnswer)) {
      finalAnswer =
        "I can only answer questions here — I'm not able to perform actions like adding or removing items on this page.";
    }

    typingEl.remove();
    appendMessage(elements.messagesEl, "assistant", finalAnswer, state.history);
  } catch (err) {
    typingEl.remove();
    if (err.name !== "AbortError") {
      appendMessage(
        elements.messagesEl,
        "assistant",
        "Something went wrong — please try again.",
        state.history,
      );
    }
    // AbortError means the user cancelled on purpose — no error message needed.
  } finally {
    state.activeController = null;
    setSendButtonState(elements.sendBtn, "send");
  }
}

function setSendButtonState(sendBtn, mode) {
  sendBtn.innerHTML = mode === "cancel" ? ICONS.stop : ICONS.send;
  sendBtn.dataset.mode = mode;
}

function setupVoiceInput(elements, send) {
  if (!elements.micBtn) return; // unsupported browser, or voice disabled in config

  const recognizer = new SpeechRecognitionAPI();
  recognizer.lang = navigator.language || "en-US";
  recognizer.continuous = false;
  recognizer.interimResults = true;

  let listening = false;

  const setListeningState = (isListening) => {
    listening = isListening;
    elements.micBtn.classList.toggle("listening", isListening);
  };

  elements.micBtn.addEventListener("click", () => {
    if (listening) {
      recognizer.stop();
      return;
    }
    try {
      recognizer.start();
      setListeningState(true);
    } catch {
      // start() throws if called while already running — ignore, the
      // existing session will just continue.
    }
  });

  recognizer.addEventListener("result", (e) => {
    const transcript = Array.from(e.results)
      .map((r) => r[0].transcript)
      .join("");
    elements.inputEl.value = transcript;

    const lastResult = e.results[e.results.length - 1];
    if (lastResult.isFinal) {
      setListeningState(false);
      send();
    }
  });

  recognizer.addEventListener("error", () => {
    setListeningState(false);
    // Permission denied, no speech detected, etc. — fail quietly, the
    // person can just type instead. No need to surface a chat error for
    // an optional input method.
  });

  recognizer.addEventListener("end", () => {
    setListeningState(false);
  });
}

function initWidget(config) {
  // Guard against double-initialization — e.g. React's StrictMode
  // intentionally double-invokes effects in development, and hot-reload
  // tooling can re-run init scripts. Without this, a second call would
  // silently create a second bubble, second panel, and duplicate event
  // listeners.
  if (window.__widgetronInitialized) {
    return;
  }

  // Being loaded inside a background content-read iframe (see
  // readDynamicPage in pageReader.js) rather than a real page visit —
  // don't self-initialize. Without this guard, the widget would spin up a
  // second hidden copy of itself inside every page it reads for context,
  // restoring THAT copy's chat history and leaking it into the very
  // context being gathered.
  if (new URLSearchParams(window.location.search).has("widgetronRead")) {
    return;
  }

  window.__widgetronInitialized = true;

  const elements = createWidgetDOM(config);
  const state = { activeController: null, history: loadHistory() };

  // Re-render any messages from a previous page's chat session.
  state.history.forEach((msg) => {
    appendMessage(elements.messagesEl, msg.role, msg.text, null); // null: don't re-save what we just loaded
  });

  const send = () => {
    if (elements.sendBtn.dataset.mode === "cancel") {
      state.activeController?.abort();
      return;
    }
    const text = elements.inputEl.value.trim();
    if (!text) return;
    elements.inputEl.value = "";
    handleSendMessage(text, elements, config, state);
  };

  elements.sendBtn.addEventListener("click", send);
  elements.inputEl.addEventListener("keydown", (e) => {
    if (e.key === "Enter") send();
  });

  setupVoiceInput(elements, send);
}

export { createProvider, initWidget as init };
